DX = -0.6
def shift(v):
    if isinstance(v, list) and len(v) in (2, 3) and all(isinstance(x, (int, float)) for x in v) and v[0] > 2.5: return [round(v[0] + DX, 3)] + v[1:]
    if isinstance(v, list): return [shift(x) for x in v]
    if isinstance(v, dict): return {kk: (vv if kk in ("f", "kicks", "size") else shift(vv)) for kk, vv in v.items()}
    return v
